import{_ as L,a0 as t,w as o,s as u,ao as s,I as r,x as l,a1 as a,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"12 個全球認可的 Linux 認證 | LCTT x X-CMD","titleTemplate":false,"description":"12 個全球認可的 Linux 認證 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"12 個全球認可的 Linux 認證 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"12 個全球認可的 Linux 認證 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150604 12 Globally Recognized Linux Certifications","title":"12 個全球認可的 Linux 認證","tag":"201506","desc":""},"relativePath":"201506/20150604 12 Globally Recognized Linux Certifications.md","filePath":"[post].md"}'),x={name:"201506/20150604 12 Globally Recognized Linux Certifications.md"};function C(S,i,h,p,c,d){const n=t("Link");return o(),u("div",null,[i[13]||(i[13]=s('<h1 id="_12-個全球認可的-linux-認證" tabindex="-1">12 個全球認可的 Linux 認證 <a class="header-anchor" href="#_12-個全球認可的-linux-認證" aria-label="Permalink to “12 個全球認可的 Linux 認證”">​</a></h1><p>大家好，今天我們將會認識一些非常有價值的全球認可的Linux認證。Linux認證是不同的Linux專業機構在全球範圍內進行的認證程序。Linux認證可以讓Linux專業人才可以在服務器領域或者相關公司等等這些地方更容易獲得Linux相關的工作。Linux認證評估一個人在Linux的各個領域裏的專業程度。有很多不錯的Linux專業機構提供不同的Linux認證。但是，在公司謀取一份工作時全球僅有少數被非常認可的Linux認證含金量很高，這些工作包括管理服務器，虛擬化，安裝系統與軟件，配置程序，應用支持和其他Linux操作系統相關的東西。隨着全球使用Linux操作系統的服務器的增長，拉動了對於Linux專業人才的需求。為了更好的證明Linux專業技術水平，在全球看來，更好的、著名的認證總是有着更高的優先級。</p><p>這裏是一些全球認可的Linux認證，我們接下來將會一一談到。</p><h3 id="_1-comptia-linxu" tabindex="-1">1. CompTIA Linxu+ <a class="header-anchor" href="#_1-comptia-linxu" aria-label="Permalink to “1. CompTIA Linxu+”">​</a></h3><p>CompTIA Linux+ 是LPI（Linux Professional Institute，Linux專業委員會）主辦的一個Linux認證，在全世界範圍內提供培訓。其提供的Linux相關知識，可以用於從事一大批Linux相關專業的工作，如Linux管理員、高級網絡管理員、系統管理員、Linux資料庫管理員和Web管理員。如果任何人想從事安裝和維護Linux操作系統，該課程會幫助他達到認證要求，並且通過提供對Linux系統更寬闊的認識，能夠為通過考試做好準備。LPI的CompTIA Linux+認證的主要目的就是，提供給證書持有者足夠紮實的，關於安裝軟件、操作、管理和設備排障的知識。我們可以付出一定的費用、時間和努力，完成CompTIA Linux+，同時獲得三個業內認可的證書：<strong>LPI LPIC-1</strong>和<strong>SUSE Certified Linux Administrator （CLA）</strong>證書。</p><ul><li><strong>認證代碼</strong> : LX0-103，LX0-104（2015年3月30日啓動）或者LX0-101，LX0-102</li><li>題目數量：每次考試60道題</li><li>題目類型：多選</li><li>考試時長：90分鐘</li><li>要求：A+，Network+，並且有至少12個月的Linux管理經驗</li><li>分數線：500 （對於200-800的範圍來説）</li><li>語言：英語，將來會有德語，葡萄牙語，繁體中文，西班牙。</li><li>有效期：認證後三年有效</li></ul><p><strong>注意</strong>：不同系列的考試不能合併。如果你考的是LX0-101，那麼你必須考LX0-102完成認證。同樣的，LX0-103和LX0-104又是一個系列。LX0-103和LX0-104系列是LX0-101和LX0-102系列的升級版。</p><h3 id="_2-lpic" tabindex="-1">2. LPIC <a class="header-anchor" href="#_2-lpic" aria-label="Permalink to “2. LPIC”">​</a></h3><p>LPIC，全稱Linux專業委員會認證（ Linux Professional Institute Certification），是Linux專業委員會的一個Linux認證程序。這是一個多級別的認證程序，要求在每個級別通過一系列（通常是兩個）的認證考試。該認證有三個級別，包括初級水平認證 <strong>LPIC-1</strong> ，高級水平認證 <strong>LPIC-2</strong>和最高水平認證 <strong>LPIC-3</strong>。前兩個認證側重於 <strong>Linux系統管理</strong>，而最後一個認證側重一些專業技能，包括虛擬化和安全。為了得到 <strong>LPIC-3</strong> 認證，一個持有有效的 <strong>LPIC-1</strong> 與<strong>LPIC-2</strong> 認證的考生必須通過300複雜環境測試、303安全測試、304虛擬化測試和高可用性測試中的一個。<strong>LPIC-1</strong>認證按照證書持有者可以通過運行Linux，使用命令列界面和基本的網絡知識安裝，維護，配置等任務而設計，LPIC-2測試考生是否作為管理中小型混合網絡的候選人。LPIC-3認證是為企業級Linux專業技能設計所設計，代表了最高的專業水平和不針對特定 Linux 發行版的行業認證。</p><ul><li><strong>認證代碼</strong>：LPIC-1（101和102），LPIC-2（201和202）和LPIC-3（300，303或者304）</li><li>題目類型：60個多項選擇</li><li>考試時長：90分鐘</li><li>要求：無，建議有 Linux Essentials 認證</li><li>分數線：500（在200-800的範圍內）</li><li>語言：LPIC-1：英語，德語，意大利語，葡萄牙語，西班牙語（現代），漢語（簡體），漢語（繁體），日語</li><li>LPIC-2：英語，德語，葡萄牙語，日語</li><li>LPIC-3：英語，日語</li><li>有效期：退休之後五年內仍然有效</li></ul><h3 id="_3-oracle-linux-oca" tabindex="-1">3.Oracle Linux OCA <a class="header-anchor" href="#_3-oracle-linux-oca" aria-label="Permalink to “3.Oracle Linux OCA”">​</a></h3><p>Oracle聯合認證（OCA）為個人而定製，適用於那些想證明其部署和管理Oracle Linux操作系統的知識牢固的人。該認證專業知識僅僅針對Oracle Linux發行版，這個系統完全是為Oracle產品特別剪裁的，可以運行Oracle設計的系統，包括Oracle Exadata資料庫服務器，Oracle Exalytics In-Memory 服務器，Oracle Exalogic 均衡雲，和Oracle資料庫應用等。Oracle Linux的“堅不可摧企業內核”為企業應用帶來了高性能、高擴展性和穩定性。OCA認證覆蓋瞭如管理本地磁盤設備、管理文件系統、安裝和移除Solaris包與補丁，優化系統啓動過程和系統進程。這是拿到OCP證書系列的第一步。OCA認證以其前身為Sun Certified Solaris Associate（SCSAS）而為人所知。</p><ul><li><strong>認證代碼</strong>：OCA</li><li>題目類型：75道多項選擇</li><li>考試時長：120分鐘</li><li>要求：無</li><li>分數線：64%</li><li>有效期：永遠有效</li></ul><h3 id="_4-oracle-linux-ocp" tabindex="-1">4. Oracle Linux OCP <a class="header-anchor" href="#_4-oracle-linux-ocp" aria-label="Permalink to “4. Oracle Linux OCP”">​</a></h3><p>Oracle專業認證(OCP)是Oracle公司為Oracle Linux提供的一個認證，覆蓋更多的進階知識和技能，對於一個Oracle Linux管理員來説。它囊括的知識有配置網絡接口、管理交換分區配置、崩潰轉儲、管理軟件、資料庫和重要文件。OCP認證是技術性專業知識和專業技能的基準測試，這些知識與技能需要在公司裏廣泛用於開發、部署和管理應用、中間件和資料庫。Oracle Linux OCP的工作機會在增長，這得益於工作市場和經濟發展。根據考試綱領，證書持有者有能力勝任安全管理、為Oracle 資料庫準備Oracle Linux系統、排除故障和進行恢復操作、安裝軟件包、安裝和配置內核模組、維護交換空間、完成用户和組管理、創建文件系統、配置邏輯卷管理（LVM）、文件分享服務等等。</p><ul><li><strong>認證代碼</strong>：OCP</li><li>題目類型：60至80道多項選擇題</li><li>考試時長：120分鐘</li><li>要求：Oracle Linux OCA</li><li>分數線：64%</li><li>有效期：永遠有效</li></ul><h3 id="_5-rhcsa" tabindex="-1">5. RHCSA <a class="header-anchor" href="#_5-rhcsa" aria-label="Permalink to “5. RHCSA”">​</a></h3><p>RHCSA是紅帽公司作為紅帽認證系統工程師推出的一個認證程序。RHCSA們是指一些擁有在著名的紅帽Linux環境下完成核心繫統管理技能和能力的人。這是一個入門級的認證程序，關注在系統管理上的實際勝任能力，包括安裝、配置一個紅帽Linux系統，接入一個可用的網絡提供網絡服務。一個紅帽認證的系統管理員可以理解和使用基本的工具，用以處理文件、目錄、命令列環境和文檔；操作運行中的系統，包括以不同的啓動級別啓動、識別進程、開啓和停止虛擬機和控制服務；使用分區和邏輯卷配置本地存儲；創建和配置文件系統和文件系統屬性，包括權限、加密、訪問控制列表和網絡文件系統；部署配置和維護系統，包括軟件安裝、更新和核心服務；管理用户和組，包括使用一箇中心的目錄用於驗證；安全性的工作，包括基本的基本防火牆和SELinux配置。要獲得RHCE和其他認證，首先得認證過RHCSA。</p><ul><li><strong>認證代碼</strong>：RHCSA</li><li>課程代碼：RH124，RH134和RH199</li><li>考試代碼：EX200</li><li>考試時長：21-22小時，取決於選擇的課程</li><li>要求：無。有一些Linux基礎知識更好</li><li>分數線：300總分，210過（70%）</li><li>有效期：3年</li></ul><h3 id="_6-rhce" tabindex="-1">6. RHCE <a class="header-anchor" href="#_6-rhce" aria-label="Permalink to “6. RHCE”">​</a></h3><p>RHCE，也叫做紅帽認證工程師，是一箇中到高級水平的認證程序，為一些想要學習更多技能和知識，成為一個負責紅帽企業Linux的高級系統管理員的RHCSA開設的，RHCE應該有能力、知識和技能來配置靜態路由、包過濾、NAT、設定內核運行參數、配置一個ISCSI初始化程序，生成併發送系統用量報告、使用shell腳本自動完成系統維護任務、配置系統日誌，包括遠程日誌、提供網絡服務如HTTP/HTTPS、FTP、NFS、SMB、SMTP、SSH和NTP等等。推薦希望獲得更多高級水平的認證的RHCSA們、已經完成系統管理員I，II和III、或者已經完成RHCE 快速跟進培訓的人們參加認證。</p><ul><li><strong>認證代碼</strong>：RHCE</li><li>課程代碼：RH124，RH134，RH254和RH199</li><li>考試代碼：EX200和EX300</li><li>考試時長：21-22個小時，取決於所選課程</li><li>要求：一個RHCSA證書</li><li>分數線：300總分，210過（70%）</li><li>有效期：3年</li></ul><h3 id="_7-rhca" tabindex="-1">7. RHCA <a class="header-anchor" href="#_7-rhca" aria-label="Permalink to “7. RHCA”">​</a></h3><p>RHCA即紅帽認證架構師，是紅帽公司的一個認證程序。它的關注點在系統管理的實際能力，包括安裝和配置一個紅帽Linux系統，並加入到一個可用網絡中運行網絡服務。RHCA是所有紅帽認證中最高水平的認證。考生需要選擇他們希望針對的領域，或者選擇合格的紅帽認證的任意組合來創建一個他們自己的領域。這裏有三個主要的領域：數據中心、雲和應用平台。精通數據中心領域的RHCA能夠運行、管理數據中心；而熟悉雲的可以創建、配置和管理私有云和混合雲、雲應用平台以及使用紅帽企業Linux平台的靈活存儲方案；精通應用平台集合的RHCA擁有技能如安裝、配置和管理紅帽JBoss企業應用平台和應用，雲應用平台和混合雲環境，藉助紅帽的OpenShift企業版，使用紅帽JBoss數據虛擬化技術從多個資源裏組合數據。</p><ul><li><strong>認證代碼</strong>：RHCA</li><li>課程代碼：CL210，CL220.CL280，RH236，RH318，RH413，RH436，RH442，JB248和JB450</li><li>考試代碼：EX333，EX401，EX423或者EX318，EX436和EX442</li><li>考試時長：21-22個小時，取決於所選課程</li><li>要求：未過期的RHCE證書</li><li>分數線：300總分，210過（70%）</li><li>有效期：3年</li></ul><h3 id="_8-suse-cla" tabindex="-1">8. SUSE CLA <a class="header-anchor" href="#_8-suse-cla" aria-label="Permalink to “8. SUSE CLA”">​</a></h3><p>SUSE認證Linux管理員（SUSE CLA）是SUSE推出的一個初級認證，關注點在SUSE Linux企業服務器環境下的日常任務管理。為了獲得SUSE CLA認證，不用必須完成課程任務，只需要通過考試就能獲得認證。SUSE CLA們能夠、也有技術去使用Linux桌面、定位並利用幫助資源、管理Linux文件系統、用Linux Shell和命令列工作、安裝SLE 11 SP22、管理系統安裝、硬件、備份和恢復、用YaST管理Linux、Linux進程和服務、存儲、配置網絡、遠程接入、SLE 11 SP2監控，任務自動化和管理用户訪問和安全工作。我們可以同時獲得SUSE CLA，LPIC-1和CompTIA Linux認證，因為SUSE，Linux Professional Institute和CompATI合作提供了這個同時獲得三個Linux認證的機會。</p><ul><li><strong>認證代碼</strong>：SUSE CLA</li><li>課程代碼：3115，3116</li><li>考試代碼：050-720，050-710</li><li>問題類型：多項選擇</li><li>考試時長：90分鐘</li><li>要求：無</li><li>分數線：512</li></ul><h3 id="_9-suse-clp" tabindex="-1">9. SUSE CLP <a class="header-anchor" href="#_9-suse-clp" aria-label="Permalink to “9. SUSE CLP”">​</a></h3><p>SUSE認證Linux專業人員（CLP）是一個認證程序，為那些希望獲得關於SUSE Linux企業服務器更多高級且專業的知識的人而服務。SUSE CLP是通過SUSE CLA認證後的下一步。應該通過CLA的考試並擁有證書，然後通過完成CLP的考試才能獲得CLP的認證。通過SUSE CLP認證的人員有能力完成安裝和配置SLES 11系統、維護文件系統、管理軟件包、進程、打印、配置基礎網絡服務、samba、Web服務器、使用IPv6、創建和運行bash shell腳本。</p><ul><li><strong>認證代碼</strong>：SUSE CLP</li><li>課程代碼：3115，3116和3117</li><li>考試代碼：050-721，050-697</li><li>考試類型：手寫</li><li>考試時長：180分鐘</li><li>要求：SUSE CLA 認證</li></ul><h3 id="_10-suse-cle" tabindex="-1">10. SUSE CLE <a class="header-anchor" href="#_10-suse-cle" aria-label="Permalink to “10. SUSE CLE”">​</a></h3><p>SUSE認證Linux工程師(CLE)是一個工程師級別的高級認證，為那些已經通過CLE考試的人準備。為了獲得CLE認證，人們需要已經獲得SUSE CLA和CLP的認證。獲得CLE認證的人員擁有架設複雜SUSE Linux企業服務器環境的技能。CLE認證過的人可以配置基本的網絡服務、管理打印、配置和使用Open LDAP、samba、IPv6、完成服務器健康檢測和性能調優、創建和執行shell腳本、部署SUSE Linux企業板、通過Xen實現虛擬化等等。</p><ul><li><strong>認證代碼</strong>：SUSE CLE</li><li>課程代碼：3107</li><li>考試代碼：050-723</li><li>考試類型：手寫</li><li>考試時長：120分鐘</li><li>要求：SUSE CLP 10或者11證書</li></ul><h3 id="_11-lfcs" tabindex="-1">11. LFCS <a class="header-anchor" href="#_11-lfcs" aria-label="Permalink to “11. LFCS”">​</a></h3><p>Linux基金會認證系統管理員（LFCS）認證考生使用Linux和通過終端環境使用Linux的知識。LFCS是Linux基金會的一個認證程序，為使用Linux操作系統工作的系統管理員和工程師準備。Linux基金會聯合業內專家、Linux內核社區，測試考生的核心領域、關鍵技能、知識和應用能力。通過LFCS認證的人員擁有一些技能、知識和能力，包括在命令列下編輯和操作文件、管理和處理文件系統與存儲的錯誤、聚合分區作為LVM設備、配置交換分區、管理網絡文件系統、管理用户帳號/權限和屬組、創建並執行bash shell腳本、安裝/升級/移除軟件包等等。</p><ul><li><strong>認證代碼</strong>：LFCS</li><li>課程代碼：LFCS201，LFCS220（可選）</li><li>考試代碼：LFCS 考試</li><li>考試時長：2小時</li><li>要求：無</li><li>分數線：74%</li><li>語言：英語</li><li>有效期：兩年</li></ul><h3 id="_12-lfce" tabindex="-1">12. LFCE <a class="header-anchor" href="#_12-lfce" aria-label="Permalink to “12. LFCE”">​</a></h3><p>Linux基金會認證工程師（LFCE），是Linux基金會為Linux工程師推出的認證。相比於LFCS，通過LFCE認證的人員在Linux方面擁有更大範圍的技能。這是一個工程師級別的高級認證程序。LFCE認證的人具備一些網絡管理方面的技能和能力，如配置網絡服務、配置包過濾、監控網絡性能、IP流量、配置文件系統和文件服務、網絡文件系統、從倉庫安裝/升級軟件包、管理網絡安全、配置iptables、http服務、代理服務、郵件服務等等。由於其為高級工程級別的認證程序，所以普遍認為相比LFCS，學習和通過的難度更大些。</p><ul><li><strong>認證代碼</strong>：LFCE</li><li>課程代碼：LFS230</li><li>考試代碼：LFCE 考試</li><li>考試時長：2小時</li><li>要求：認證過LFCS</li><li>分數線：72%</li><li>語言：英語</li><li>有效期：2年</li></ul><h3 id="我們發現的情況-這僅僅是我們的觀點" tabindex="-1">我們發現的情況（這僅僅是我們的觀點）### <a class="header-anchor" href="#我們發現的情況-這僅僅是我們的觀點" aria-label="Permalink to “我們發現的情況（這僅僅是我們的觀點）###”">​</a></h3><p>最近的調查表明，在不同的高端招聘代理中，稱80%的Linux工作描述更傾向於紅帽的認證。如果你是一個學生/新手，並且想學習Linux，那麼我們建議選擇越來越流行的Linux基金會認證，或者CompTIA Linux也可以是一個選擇。如果你已經瞭解了oracle或suse，或者在他們的產品上工作，那oracle/suse的認證會更好些，如果你在公司裏工作了，這些認證會對你的職業生涯成長有幫助:-)</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這個世界上，成千上萬的大公司正在運行跑着Linux操作系統的服務器和主框架機，為了在這些服務器上管理、配置和工作，總是存在着對Linux技術/專業知識高度認證的需求。這些國際上承認的認證對某些人在Linux的職業生涯扮演很重要的角色。這些遍佈全球的公司運行着Linux，需要Linux工程師、系統管理員和已經獲得認證且在Linux相關領域幹得不錯的人員。全球認可的Linux認證，對於專業知識和職業生涯的輝煌都是重中之重，所以好好準備考試並獲得認證，對於在Linux建立職業生涯是一個很好的選擇。如果你有任何問題，想法，反饋，請寫在下方的評論框裏，讓我們好知道哪些東西需要添加或者改進。謝謝！😃</p><hr>',45)),r("p",null,[i[1]||(i[1]=l("via: ",-1)),a(n,{href:"http://linoxide.com/linux-how-to/12-globally-recognized-linux-certifications/"},{default:e(()=>[...i[0]||(i[0]=[l("http://linoxide.com/linux-how-to/12-globally-recognized-linux-certifications/",-1)])]),_:1})]),r("p",null,[i[5]||(i[5]=l("作者：",-1)),a(n,{href:"http://linoxide.com/author/arunp/"},{default:e(()=>[...i[2]||(i[2]=[l("Arun Pyasi",-1)])]),_:1}),i[6]||(i[6]=l(" 譯者：",-1)),a(n,{href:"https://github.com/wi-cuckoo"},{default:e(()=>[...i[3]||(i[3]=[l("wi-cuckoo",-1)])]),_:1}),i[7]||(i[7]=l(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:e(()=>[...i[4]||(i[4]=[l("wxy",-1)])]),_:1})]),r("p",null,[i[10]||(i[10]=l("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[8]||(i[8]=[l("LCTT",-1)])]),_:1}),i[11]||(i[11]=l(" 原創翻譯，",-1)),a(n,{href:"https://linux.cn/"},{default:e(()=>[...i[9]||(i[9]=[l("Linux中國",-1)])]),_:1}),i[12]||(i[12]=l(" 榮譽推出",-1))])])}const A=L(x,[["render",C]]);export{g as __pageData,A as default};
